HAVING SUM(mtt.Quantity * (mtt.Rate - COALESCE(CASE WHEN mt.Credit > 0 THEN Credit ELSE 0 END + CASE WHEN mt.Debit < 0 THEN Debit ELSE 0 END end)) ) / COUNT(*) < (
